/*
 * arch/m68k/memcpy.c - memcpy for the m68k kernel build
 *
 * Generated by: Claude Opus 5.5
 *
 * A compiler-support routine, not a function of the SAU2 image: GCC emits
 * calls to memcpy for structure assignments and large by-value copies
 * (e.g. PROC2_$CLEANUP_HANDLERS_INTERNAL's copy of the 0xE4-byte process
 * entry, the ring and network request records) even under -ffreestanding
 * -fno-builtin, and the kernel has no libc.  The Pascal compiler open-coded
 * the same copies as `move.l (A0)+,(A1)+' loops.  Built for the m68k target
 * only (Makefile, ARCH_M68K_SRCS); host builds use libc's.
 *
 * A plain byte loop: callers pass any alignment.  The loop-distribution
 * pass is switched off for this function so GCC cannot turn the loop back
 * into a call to memcpy.
 */

#include "arch/m68k/arch.h"

__attribute__((optimize("no-tree-loop-distribute-patterns")))
void *(memcpy)(void *dst, const void *src, __SIZE_TYPE__ n)
{
    unsigned char *d = (unsigned char *)dst;
    const unsigned char *s = (const unsigned char *)src;

    while (n != 0) {
        *d++ = *s++;
        n--;
    }
    return dst;
}
